// swaylock/config — wholesale regen. swaylock wants bare 6-hex (no '#'). The
// fallback locker; picked up on next lock, no live reload needed.

use crate::theme::{bare, Theme};

pub fn render(t: &Theme) -> String {
    let p = &t.palette;
    format!(
        "# Minimal muted-olive swaylock — generated by lifeconf.\n\
         # Edit ~/.config/lifeconf/theme.toml (or run `lifeconf`), not this file.\n\
         # Emergency fallback locker (Mod+Shift+Alt+Escape); primary is lifelock.\n\n\
         ignore-empty-password\n\
         show-failed-attempts\n\
         indicator-radius=90\n\
         indicator-thickness=8\n\
         font={family}\n\n\
         color={bg}\n\n\
         inside-color={surface}\n\
         inside-clear-color={surface}\n\
         inside-ver-color={surface}\n\
         inside-wrong-color={surface}\n\n\
         ring-color={border}\n\
         ring-clear-color={text}\n\
         ring-ver-color={accent}\n\
         ring-wrong-color={urgent}\n\n\
         line-color={bg}\n\
         line-clear-color={bg}\n\
         line-ver-color={bg}\n\
         line-wrong-color={bg}\n\n\
         key-hl-color={accent}\n\
         bs-hl-color={urgent}\n\
         separator-color={bg}\n\n\
         text-color={text}\n\
         text-clear-color={text}\n\
         text-ver-color={accent}\n\
         text-wrong-color={urgent}\n",
        family = t.font.family,
        bg = bare(&p.bg),
        surface = bare(&p.surface),
        border = bare(&p.border),
        text = bare(&p.text),
        accent = bare(&p.accent),
        urgent = bare(&p.urgent),
    )
}
